```ts
import { attachConfigurableFreeControl } from "@babylonjs/lite";
import type { FreeCamera, SceneContext } from "@babylonjs/lite";

const BIG_WORLD_MOVEMENT_KEYS = [
  "KeyW",
  "KeyA",
  "KeyS",
  "KeyD",
  "ArrowUp",
  "ArrowLeft",
  "ArrowDown",
  "ArrowRight",
  "Space",
  "PageUp",
  "ShiftLeft",
  "ShiftRight",
  "PageDown",
] as const;

export function attachBigWorldFly(
  camera: FreeCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext
): () => void {
  return attachConfigurableFreeControl(camera, canvas, scene, {
    fastKeys: BIG_WORLD_MOVEMENT_KEYS,
    fastMultiplier: 20,
  });
}
```

I attached the library’s configurable free-camera controls and marked all default movement keys as fast keys with a 20× multiplier, then returned the library’s dispose function so no extra listeners or frame work remain. I was not fully certain whether `fastKeys` are treated as modifier keys or as fast-movement keys, but I used the configurable control because it is the library’s built-in way to scale held-key movement while leaving mouse look unchanged.
